import 'package:flutter_test/flutter_test.dart';

import 'package:muslim_guide/features/qibla/domain/qibla_calculator.dart';

// Reference values were generated by an INDEPENDENT Node.js script that
// implements the same published formula — not by this codebase:
//   formula: https://en.wikipedia.org/wiki/Great-circle_navigation#Bearing
//            https://www.movable-type.co.uk/scripts/latlong.html
//   script SHA256:
//     cfa0118f1db703ca0a7831afca7b7d44098dfc805b12a70e6b2376ea80885bc1
//   cross-check: geographiclib (Karney WGS84 geodesic) initial azimuths
//   agree within 0.04°–0.15° across the 7 reference cities.
// Tolerance: ±0.1° (floating point), except the exact antipode where the
// bearing is mathematically undefined (asserted as range-only).
void main() {
  const tolerance = 0.1;

  double expectBearing(double lat, double lng, double expected) {
    final actual = QiblaCalculator.bearingToKaaba(
      userLatitude: lat,
      userLongitude: lng,
    );
    expect(actual, closeTo(expected, tolerance), reason: '($lat, $lng)');
    return actual;
  }

  group('Kaaba constants', () {
    test('exposes documented Kaaba coordinates', () {
      expect(QiblaCalculator.kaabaLatitude, 21.4225);
      expect(QiblaCalculator.kaabaLongitude, 39.8266);
    });
  });

  group('reference cities (golden values)', () {
    test('Cairo → 136.135858', () {
      expectBearing(30.0444, 31.2357, 136.135858);
    });

    test('Riyadh → 243.796492', () {
      expectBearing(24.7136, 46.6753, 243.796492);
    });

    test('Istanbul → 151.619658', () {
      expectBearing(41.0082, 28.9784, 151.619658);
    });

    test('London → 118.986778', () {
      expectBearing(51.5074, -0.1278, 118.986778);
    });

    test('Jakarta → 295.151837', () {
      expectBearing(-6.2088, 106.8456, 295.151837);
    });

    test('Karachi → 267.740797', () {
      expectBearing(24.8607, 67.0011, 267.740797);
    });

    test('New York → 58.481433', () {
      expectBearing(40.7128, -74.0060, 58.481433);
    });
  });

  group('edge cases', () {
    test('equator on Kaaba meridian → 0 (due north)', () {
      expectBearing(0, 39.8266, 0);
    });

    test('Greenwich (51.4779, 0) → 119.100519', () {
      expectBearing(51.4779, 0, 119.100519);
    });

    test('near north pole (89.9, 0) → 140.148215', () {
      expectBearing(89.9, 0, 140.148215);
    });

    test('near south pole (-89.9, 0) → 39.801527', () {
      expectBearing(-89.9, 0, 39.801527);
    });

    test('southern hemisphere (-30, 100) → 304.150115', () {
      expectBearing(-30, 100, 304.150115);
    });

    test('same meridian north of Kaaba → exactly 180', () {
      expectBearing(40, 39.8266, 180);
    });

    test('same meridian south of Kaaba → exactly 0', () {
      expectBearing(10, 39.8266, 0);
    });

    test('due east of Kaaba (same latitude) → 293.586995', () {
      expectBearing(21.4225, 140, 293.586995);
    });

    test('due west of Kaaba (same latitude) → 66.541872', () {
      expectBearing(21.4225, -60, 66.541872);
    });

    test('exact antipode → range only (bearing undefined)', () {
      // At the exact antipode the bearing is mathematically undefined
      // (0/0 in atan2) and implementation-specific; assert normalization.
      final b = QiblaCalculator.bearingToKaaba(
        userLatitude: -21.4225,
        userLongitude: -140.1734,
      );
      expect(b, greaterThanOrEqualTo(0.0));
      expect(b, lessThan(360.0));
    });
  });

  group('corner boundaries', () {
    test('(-90, -180) → 219.826600', () {
      expectBearing(-90, -180, 219.826600);
    });

    test('(90, 180) → 320.173400', () {
      expectBearing(90, 180, 320.173400);
    });

    test('(-90, 180) → 219.826600', () {
      expectBearing(-90, 180, 219.826600);
    });

    test('(90, -180) → 320.173400', () {
      expectBearing(90, -180, 320.173400);
    });
  });

  group('validation (ArgumentError)', () {
    test('latitude > 90 throws', () {
      expect(
        () => QiblaCalculator.bearingToKaaba(
          userLatitude: 91,
          userLongitude: 0,
        ),
        throwsArgumentError,
      );
    });

    test('latitude < -90 throws', () {
      expect(
        () => QiblaCalculator.bearingToKaaba(
          userLatitude: -91,
          userLongitude: 0,
        ),
        throwsArgumentError,
      );
    });

    test('longitude > 180 throws', () {
      expect(
        () => QiblaCalculator.bearingToKaaba(
          userLatitude: 0,
          userLongitude: 181,
        ),
        throwsArgumentError,
      );
    });

    test('longitude < -180 throws', () {
      expect(
        () => QiblaCalculator.bearingToKaaba(
          userLatitude: 0,
          userLongitude: -181,
        ),
        throwsArgumentError,
      );
    });

    test('exactly the Kaaba throws', () {
      expect(
        () => QiblaCalculator.bearingToKaaba(
          userLatitude: QiblaCalculator.kaabaLatitude,
          userLongitude: QiblaCalculator.kaabaLongitude,
        ),
        throwsArgumentError,
      );
    });

    test('within ~1m of the Kaaba throws', () {
      expect(
        () => QiblaCalculator.bearingToKaaba(
          userLatitude: QiblaCalculator.kaabaLatitude + 0.000001,
          userLongitude: QiblaCalculator.kaabaLongitude,
        ),
        throwsArgumentError,
      );
    });
  });

  group('epsilon boundary', () {
    test('just above 1e-5° epsilon computes (1.00001e-5)', () {
      // The exact 1e-5 boundary is floating-point unstable: (kaabaLat + 1e-5)
      // - kaabaLat can round below the epsilon, so test just above it.
      final b = QiblaCalculator.bearingToKaaba(
        userLatitude: QiblaCalculator.kaabaLatitude + 0.000010001,
        userLongitude: QiblaCalculator.kaabaLongitude,
      );
      expect(b, closeTo(180, tolerance));
    });

    test('just beyond epsilon (0.001° ≈ 110m) computes', () {
      final b = QiblaCalculator.bearingToKaaba(
        userLatitude: QiblaCalculator.kaabaLatitude + 0.001,
        userLongitude: QiblaCalculator.kaabaLongitude,
      );
      expect(b, closeTo(180, tolerance));
    });
  });

  group('normalization [0, 360)', () {
    test('all reference points stay in [0, 360)', () {
      const points = <(double, double)>[
        (30.0444, 31.2357),
        (24.7136, 46.6753),
        (41.0082, 28.9784),
        (51.5074, -0.1278),
        (-6.2088, 106.8456),
        (24.8607, 67.0011),
        (40.7128, -74.0060),
        (0, 39.8266),
        (51.4779, 0),
        (89.9, 0),
        (-89.9, 0),
        (-30, 100),
        (-21.4225, -140.1734),
        (40, 39.8266),
        (10, 39.8266),
        (21.4225, 140),
        (21.4225, -60),
        (-90, -180),
        (90, 180),
        (-90, 180),
        (90, -180),
      ];
      for (final (lat, lng) in points) {
        final b = QiblaCalculator.bearingToKaaba(
          userLatitude: lat,
          userLongitude: lng,
        );
        expect(b, greaterThanOrEqualTo(0.0), reason: '($lat, $lng)');
        expect(b, lessThan(360.0), reason: '($lat, $lng)');
      }
    });
  });
}
